ASSETS = ROOT / "assets"

def load_starting_data():
    with (ASSETS / "table4_utkface.csv").open(encoding="utf-8-sig", newline="") as f:
        rows = list(csv.DictReader(f))
    manifest = json.loads((ASSETS / "table4_manifest.json").read_text(encoding="utf-8"))
    assert len(rows) == 10 and len(manifest["cells"]) == 140
    assert len(manifest["columns"]) == 14
    assert all(len(row) == 15 for row in rows)
    assert rows[0]["Method"] == "Source" and rows[-1]["Method"] == "Oracle"
    return rows, manifest

def smoke_synthetic_render():
    # Exercise plotting imports and file rendering on unrelated synthetic data only.
    fig, ax = plt.subplots(figsize=(2, 1))
    ax.plot([0, 1], [1, 0])
    with tempfile.TemporaryDirectory() as td:
        out = pathlib.Path(td) / "synthetic.png"
        fig.savefig(out, dpi=50)
        assert out.exists() and out.stat().st_size > 0
    plt.close(fig)

if __name__ == "__main__":
